package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class ChapterBatchTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private File source;private Uri uri,tree;private String stamp;private AudioChapterStore.Data markers;private ChapterBatchExportActivity screen;private final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);private final AtomicInteger calls=new AtomicInteger(),active=new AtomicInteger(),maximum=new AtomicInteger();private int gateAt=1,failAt=-1;private final Map<String,Map<String,?>> prefs=new HashMap<>();private final List<File> copies=new ArrayList<>();
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<500;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception error){throw new RuntimeException(error);}});if(ready[0])return;Thread.sleep(50);}ChapterExportService.Snapshot state=ChapterExportService.state(c);fail("Timed out: "+(state==null?"no job":state.phase+" "+state.message));}
 private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private ChapterExportService service()throws Exception{java.lang.reflect.Field f=ChapterExportService.class.getDeclaredField("live");f.setAccessible(true);return (ChapterExportService)f.get(null);}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor p=ins.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){while(in.read()!=-1){}}}
 @Before public void before()throws Exception{
  for(String name:new String[]{OndaFolders.PREF,"downloaded_audio","conversion"})prefs.put(name,c.getSharedPreferences(name,0).getAll());
  tree=DocumentsContract.buildTreeDocumentUri(c.getPackageName()+".test.batchdocs","root");DocumentsContract.deleteDocument(c.getContentResolver(),DocumentsContract.buildDocumentUriUsingTree(tree,"root"));
  c.getSharedPreferences(OndaFolders.PREF,0).edit().putString("tree",tree.toString()).putBoolean("enabled",true).commit();Mp3Quality.save(c,320);File wave=AudioTestFixtures.tone(c,12000);File shared=new File(c.getCacheDir(),"shares");shared.mkdirs();source=new File(shared,"batch-source-"+UUID.randomUUID()+".wav");assertTrue(wave.renameTo(source));uri=androidx.core.content.FileProvider.getUriForFile(c,c.getPackageName()+".share",source);stamp=AudioChapterStore.stamp(c,uri);
  markers=new AudioChapterStore.Data(12000,Arrays.asList(new AudioChapterStore.Chapter(0,"Nome igual"),new AudioChapterStore.Chapter(3000,"Nome igual"),new AudioChapterStore.Chapter(6000,"Terceira / música"),new AudioChapterStore.Chapter(9000,"Última")));AudioChapterStore.save(c,uri,stamp,markers);
  ChapterExportService.converter=(context,job,descriptor,control)->{int index=calls.incrementAndGet(),parallel=active.incrementAndGet();maximum.accumulateAndGet(parallel,Math::max);try{if(index==gateAt){entered.countDown();try{if(!release.await(20,TimeUnit.SECONDS))throw new IOException("Test gate timed out");}catch(InterruptedException error){Thread.currentThread().interrupt();throw new InterruptedIOException("Cancelado");}}if(index==failAt)throw new IOException("Falha de teste nesta faixa");ChapterExportTask.run(context,job,descriptor,control);}finally{active.decrementAndGet();}};
 }
 private void open()throws Exception{screen=(ChapterBatchExportActivity)ins.startActivitySync(new Intent(c,ChapterBatchExportActivity.class).putExtra("source",uri.toString()).putExtra("stamp",stamp).putExtra("name","Coletânea de teste").putExtra("duration",12000L).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->field(screen,"data")!=null&&!(Boolean)field(screen,"loading"));}
 private void select(int...indices){ins.runOnMainSync(()->{try{ListView list=(ListView)field(screen,"list");for(int index:indices){list.setItemChecked(index,true);list.getOnItemClickListener().onItemClick(list,null,index,index);}}catch(Exception error){throw new RuntimeException(error);}});}
 private void start(int...indices)throws Exception{open();select(indices);ins.runOnMainSync(()->{try{assertTrue(((Button)field(screen,"save")).performClick());}catch(Exception error){throw new RuntimeException(error);}});assertTrue(entered.await(10,TimeUnit.SECONDS));waitFor(()->service()!=null&&ChapterExportService.state(c).batch!=null);}
 private List<ChapterBatchStore.Result> results()throws Exception{return ChapterBatchStore.results(c,ChapterExportService.state(c).batch.token);}
 private File copy(Uri uri)throws Exception{File file=File.createTempFile("batch-verify-",".mp3",c.getCacheDir());copies.add(file);try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}return file;}
 private void finishJob()throws Exception{release.countDown();waitFor(()->!ChapterExportService.state(c).running&&service()==null);}
 @After public void after()throws Exception{release.countDown();shell("input keyevent 224");shell("wm dismiss-keyguard");ins.runOnMainSync(()->{c.stopService(new Intent(c,ChapterExportService.class));if(screen!=null)screen.finish();});waitFor(()->service()==null);ChapterExportService.converter=ChapterExportTask::run;((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(ChapterExportService.NOTICE);for(File file:copies)file.delete();source.delete();DocumentsContract.deleteDocument(c.getContentResolver(),DocumentsContract.buildDocumentUriUsingTree(tree,"root"));for(Map.Entry<String,Map<String,?>> entry:prefs.entrySet()){SharedPreferences.Editor edit=c.getSharedPreferences(entry.getKey(),0).edit().clear();for(Map.Entry<String,?> item:entry.getValue().entrySet()){Object value=item.getValue();if(value instanceof String)edit.putString(item.getKey(),(String)value);else if(value instanceof Boolean)edit.putBoolean(item.getKey(),(Boolean)value);else if(value instanceof Integer)edit.putInt(item.getKey(),(Integer)value);else if(value instanceof Long)edit.putLong(item.getKey(),(Long)value);else if(value instanceof Float)edit.putFloat(item.getKey(),(Float)value);}edit.commit();}ins.waitForIdleSync();}
 @Test public void selectedTracksExportSequentiallyScreenOffAndKeepOriginalNumbers()throws Exception{
  byte[] original=java.nio.file.Files.readAllBytes(source.toPath());start(0,2);PowerManager.WakeLock wake=(PowerManager.WakeLock)field(service(),"wake");assertTrue(wake.isHeld());Mp3Quality.save(c,128);shell("input keyevent 3");shell("input keyevent 223");ins.runOnMainSync(()->screen.finish());waitFor(()->screen.isDestroyed());assertTrue(ChapterExportService.state(c).running);assertFalse(((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isInteractive());finishJob();assertEquals("done",ChapterExportService.state(c).phase);assertFalse(wake.isHeld());assertEquals(2,ChapterExportService.state(c).batch.done);assertEquals(1,maximum.get());
  List<ChapterBatchStore.Result> output=results();assertEquals(2,output.size());assertEquals(0,output.get(0).index);assertEquals(2,output.get(1).index);for(ChapterBatchStore.Result row:output){assertNotNull(row.uri);assertTrue(DocumentsContract.getDocumentId(row.uri).contains("/Onda/Áudios/"));File file=copy(row.uri);assertTrue(new ChapterExportTest().decodedRms(file,3000)>100);assertTrue(file.length()>100000);}assertTrue(DocumentsContract.getDocumentId(output.get(0).uri).contains("001 - "));assertTrue(DocumentsContract.getDocumentId(output.get(1).uri).contains("003 - "));assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));
  shell("input keyevent 224");shell("wm dismiss-keyguard");screen=(ChapterBatchExportActivity)ins.startActivitySync(ChapterExportService.state(c).screen(c).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((List<?>)field(screen,"results")).size()==2&&screen.hasWindowFocus());ins.waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap image=ins.getUiAutomation().takeScreenshot();assertNotNull(image);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"chapter-batch.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}
 }
 @Test public void cancellingSecondTrackKeepsFirstCompletedMp3()throws Exception{gateAt=2;start(0,1,2);String token=ChapterExportService.state(c).batch.token;assertEquals(1,ChapterBatchStore.results(c,token).size());ins.runOnMainSync(()->ChapterExportService.cancel(c,ChapterExportService.state(c)));waitFor(()->!ChapterExportService.state(c).running&&service()==null);assertEquals("cancelled",ChapterExportService.state(c).phase);assertEquals(1,ChapterExportService.state(c).batch.done);List<ChapterBatchStore.Result> output=ChapterBatchStore.results(c,token);assertEquals(1,output.size());assertTrue(new ChapterExportTest().decodedRms(copy(output.get(0).uri),3000)>100);assertEquals(2,calls.get());}
 @Test public void oneFailedTrackDoesNotDiscardOtherResults()throws Exception{failAt=2;start(0,1,2);finishJob();assertEquals("partial",ChapterExportService.state(c).phase);assertEquals(2,ChapterExportService.state(c).batch.done);assertEquals(1,ChapterExportService.state(c).batch.failed);List<ChapterBatchStore.Result> output=results();assertEquals(3,output.size());assertNotNull(output.get(0).uri);assertNull(output.get(1).uri);assertTrue(output.get(1).error.contains("Falha de teste"));assertNotNull(output.get(2).uri);assertEquals(1,maximum.get());}
 @Test public void selectAllClearAndRepeatedExportUseSeparateFolders()throws Exception{open();ins.runOnMainSync(()->{try{assertFalse(((Button)field(screen,"save")).isEnabled());((Button)field(screen,"all")).performClick();assertEquals(4,((ListView)field(screen,"list")).getCheckedItemCount());((Button)field(screen,"none")).performClick();assertEquals(0,((ListView)field(screen,"list")).getCheckedItemCount());assertFalse(((Button)field(screen,"save")).isEnabled());}catch(Exception error){throw new RuntimeException(error);}});select(0,1);ins.runOnMainSync(()->{try{((Button)field(screen,"save")).performClick();}catch(Exception error){throw new RuntimeException(error);}});assertTrue(entered.await(10,TimeUnit.SECONDS));finishJob();String folder=ChapterExportService.state(c).batch.folder,oldToken=ChapterExportService.state(c).batch.token;List<ChapterBatchStore.Result> before=results();byte[] first=java.nio.file.Files.readAllBytes(copy(before.get(0).uri).toPath());ins.runOnMainSync(()->{try{((Button)field(screen,"save")).performClick();}catch(Exception error){throw new RuntimeException(error);}});waitFor(()->!oldToken.equals(ChapterExportService.state(c).batch.token));finishJob();assertNotEquals(folder,ChapterExportService.state(c).batch.folder);assertArrayEquals(first,java.nio.file.Files.readAllBytes(copy(before.get(0).uri).toPath()));assertEquals(2,results().size());}
 @Test public void changedMarkersRejectFrozenSelectionBeforeCreatingFiles()throws Exception{boolean[] chosen={true,false,true,false};ChapterBatchPlan plan=ChapterBatchPlan.selected(uri,tree,stamp,"Alterada",markers,chosen,320);AudioChapterStore.save(c,uri,stamp,ChapterEdits.full(12000));ins.runOnMainSync(()->{try{assertTrue(ChapterExportService.startBatch(c,plan));}catch(IOException error){throw new RuntimeException(error);}});waitFor(()->ChapterExportService.state(c)!=null&&ChapterExportService.state(c).job.token.equals(plan.token)&&!ChapterExportService.state(c).running&&service()==null);assertEquals("error",ChapterExportService.state(c).phase);assertEquals(0,calls.get());assertTrue(ChapterExportService.state(c).message.contains("divisões"));assertTrue(ChapterBatchStore.results(c,plan.token).isEmpty());}
 @Test public void selectionSnapshotRejectsEmptyAndKeepsFrozenRows()throws Exception{try{ChapterBatchPlan.selected(uri,tree,stamp,"Vazia",markers,new boolean[4],320);fail("Empty selection accepted");}catch(IOException expected){}boolean[] selection={true,false,true,false};ChapterBatchPlan plan=ChapterBatchPlan.selected(uri,tree,stamp,"Congelada",markers,selection,320);selection[0]=false;assertEquals(2,plan.rows.size());assertEquals(0,plan.rows.get(0).index);assertEquals(2,plan.rows.get(1).index);ChapterBatchStore.save(c,plan);ChapterBatchPlan read=ChapterBatchStore.load(c,plan.token);assertEquals(plan.total,read.total);assertEquals(320,read.bitrate);assertEquals(plan.filename(plan.rows.get(0)),read.filename(read.rows.get(0)));assertNotEquals(plan.filename(plan.rows.get(0)),plan.filename(plan.rows.get(1)));try{new ChapterBatchPlan(UUID.randomUUID().toString(),uri,tree,stamp,"Inválida",12000,320,Arrays.asList(plan.rows.get(1),plan.rows.get(0))).validate();fail("Unordered selection accepted");}catch(IOException expected){}}
}
